const Skeleton* inSkeleton, float inTime) const
{
// Resize the outPoses vector if needed
if (outPoses.size() != mNumBones)
{
outPoses.resize(mNumBones);
}
// For now, just compute the pose for every bone at frame 0
const int frame = 0;
